def simulate_spread(initial_state, max_steps=500, full_grid_size=6):
    """Simulates the spread dynamics."""
    grid = initial_state.copy()
    H, W = grid.shape

    for step in range(max_steps):
        next_grid = grid.copy()

        # Store potential changes based on current grid state
        # Growth changes (Rule 1): Where 0 -> 1
        growth_targets = set()
        # Mutation changes (Rule 2): Where state flips (0->1 or 1->0)
        mutation_blocks = []

        # Iterate over all possible 2x2 blocks
        for r in range(H - 1):
            for c in range(W - 1):
                block = grid[r:r+2, c:c+2]
