                elif count == 2:
                    # Rule 2: Mark the block for mutation
                    mutation_blocks.append((r, c))

        # Apply Rule 2 mutations AFTER checking Rule 1, 
        # but based on the state *before* applying R1 changes to next_grid for this step.
        # Since Rule 1 already modified next_grid, we must be careful.
        # For simplicity in this simulation: mutations happen independently.
        # We apply mutations to the state resulting from Rule 1 application.

        for r_m, c_m in mutation_blocks:
            # Coordinates of the 2x2 block
            coords = [(r_m, c_m), (r_m, c_m+1), (r_m+1, c_m), (r_m+1, c_m+1)]

            for r_coord, c_coord in coords:
                # Flip the state in next_grid (which already includes R1 changes)
                next_grid[r_coord, c_coord] = 1 - next_grid[r_coord, c_coord]

        # Check for state stability
        if np.array_equal(grid, next_grid):
            return "STAGNATION", grid

        grid = next_grid

        # Check for full spread
        if np.all(grid == 1):
            return "FULL_SPREAD", grid

    # If max_steps reached without full spread or clear stagnation
    return "CYCLING_OR_SLOW_GROWTH", grid

